import{_ as e,o as d,c as s,a2 as t}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"Providers (CLIs)","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/providers.md","filePath":"deep-dive/providers.md","lastUpdated":1781623519000}'),a={name:"deep-dive/providers.md"};function r(c,o,l,i,n,m){return d(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="providers-clis" tabindex="-1">Providers (CLIs) <a class="header-anchor" href="#providers-clis" aria-label="Permalink to &quot;Providers (CLIs)&quot;">​</a></h1><p><code>SKILL.md</code> é um <strong>padrão cross-agent</strong>: a mesma skill roda em todos os CLIs sem mudar nada. O que difere entre eles é <strong>onde</strong> as skills ficam e <strong>como os comandos</strong> são expostos.</p><table tabindex="0"><thead><tr><th>CLI</th><th>Skills</th><th>Comandos</th><th>Instruções</th></tr></thead><tbody><tr><td><strong>Claude Code</strong></td><td><code>.claude/skills/</code></td><td><code>.claude/commands/sl.*.md</code> → <code>/sl.plan</code></td><td><code>CLAUDE.md</code></td></tr><tr><td><strong>Codex</strong></td><td><code>.codex/skills/</code></td><td><code>.codex/prompts/sl.*.md</code> → <code>/prompts:sl.plan</code></td><td><code>AGENTS.md</code></td></tr><tr><td><strong>Grok Build</strong></td><td><code>.grok/skills/</code></td><td>skills <code>sl-plan</code>, <code>sl-build</code>… (slash de skill)</td><td><code>AGENTS.md</code></td></tr><tr><td><strong>Antigravity</strong></td><td><code>.agent/skills/</code> (CLI) · <code>.agents/skills/</code> (UI)</td><td>idem Grok</td><td><code>AGENTS.md</code></td></tr></tbody></table><h2 id="como-cada-um-carrega" tabindex="-1">Como cada um carrega <a class="header-anchor" href="#como-cada-um-carrega" aria-label="Permalink to &quot;Como cada um carrega&quot;">​</a></h2><ul><li><strong>Claude Code</strong> — comandos em markdown (<code>/sl.x</code>), skills em <code>SKILL.md</code>, subagentes em <code>.claude/agents/</code>.</li><li><strong>Codex</strong> — comandos viram <em>custom prompts</em> (<code>/prompts:sl.x</code>); skills em <code>~/.codex/skills</code>; instruções globais em <code>AGENTS.md</code>.</li><li><strong>Grok Build</strong> — reconhece o formato de skill da Anthropic; skills aparecem como slash commands. Cada comando do método é exposto como a skill <code>sl-&lt;x&gt;</code>.</li><li><strong>Antigravity</strong> (ex-Gemini) — skills no escopo de projeto em <code>.agent/skills/</code> (CLI) e <code>.agents/skills/</code> (UI); global em <code>~/.gemini/config/skills/</code>.</li></ul><h2 id="por-que-os-comandos-viram-skills-em-grok-antigravity" tabindex="-1">Por que os comandos viram skills em Grok/Antigravity <a class="header-anchor" href="#por-que-os-comandos-viram-skills-em-grok-antigravity" aria-label="Permalink to &quot;Por que os comandos viram skills em Grok/Antigravity&quot;">​</a></h2><p>Esses CLIs usam <strong>skills como mecanismo de slash command</strong>, então cada workflow (<code>/sl.plan</code>, <code>/sl.build</code>…) é empacotado como uma skill <code>sl-plan</code>, <code>sl-build</code> etc. O conteúdo é o mesmo do comando — só muda o formato de invocação.</p><h2 id="instrucoes-globais-agents-md" tabindex="-1">Instruções globais (AGENTS.md) <a class="header-anchor" href="#instrucoes-globais-agents-md" aria-label="Permalink to &quot;Instruções globais (AGENTS.md)&quot;">​</a></h2><p>Codex, Grok e Antigravity leem um <code>AGENTS.md</code> na raiz do projeto. Ele descreve o método, aponta o gateway <code>sl</code> e documenta o runtime <code>.codesl/</code>. No Claude Code, o equivalente é o <code>CLAUDE.md</code>.</p><div class="info custom-block"><p class="custom-block-title">Cobertura</p><p>Hoje o framework empacota <strong>Claude Code, Codex, Grok e Antigravity</strong>. Outros alvos do método original (cursor, windsurf, etc.) não estão incluídos — dependiam do build tool original e não faziam parte deste pacote.</p></div>',10)])])}const p=e(a,[["render",r]]);export{u as __pageData,p as default};
